import type { ListeningScenario, Detail } from './listening-model.js';

const rows = (items: string[]): Detail[] => items.map(item => {
  const [label, answer, reason, alternatives] = item.split('|');
  return [label!, answer!, reason!, alternatives?.split(';')];
});
const make = (title: string, topic: string, context: string, closing: string, band: number, items: string[], style?: ListeningScenario['style']): ListeningScenario => ({ title, topic, context, closing, band, details: rows(items), style });

